INSERT INTO capital_source_profiles (institution_id,capital_types,sectors,geographies,minimum_readiness,instrument_notes,eligibility_notes,evidence_urls) SELECT ip.id,'["debt","equity","dfi","blended_finance","grant_catalytic"]'::jsonb,'["manufacturing","agribusiness","energy","transport","health","education","water","infrastructure","finance","services"]'::jsonb,'["Nigeria","Africa"]'::jsonb,70,'Loans, guarantees, equity, quasi-equity, trade finance and technical assistance may be available depending on eligibility and transaction structure.','Eligible private-sector operations generally need to be commercially and financially sound and demonstrate development impact; specific eligibility and diligence requirements apply.','["https://www.afdb.org/en/topics-and-sectors/sectors/private-sector","https://www.afdb.org/en/private-sector/financial-solutions","https://www.afdb.org/en/private-sector/how-work-us"]'::jsonb FROM institutional_profiles ip WHERE ip.organization_name='African Development Bank' AND NOT EXISTS (SELECT 1 FROM capital_source_profiles csp WHERE csp.institution_id=ip.id);